140	///   or in a directory that takes no new file); this is checked for every target before the first write.
141	/// - Manifest parse/write failures (malformed TOML/JSON, unsupported format).
142	/// - Git subprocess failures (`git add`/`git rm --cached` non-zero exit).
143	/// - I/O errors writing changelog sections or `pre.json`.
144	pub fn apply_version_plan<R: CommandRunner>(
145	    root: &Path,
146	    plan: &VersionPlan,
147	    runner: &R,
148	    opts: &ApplyOptions,
149	    permit: &ApplyPermit,
150	) -> Result<ApplyOutcome, GraphError> {
151	    let mut outcome = ApplyOutcome::default();
152	    let mut modified_paths = Vec::new();
153	    let mut deferred_deletions = Vec::new();
154	
155	    let ctx = OpenContext::for_workspace_root(root)?;
156	    preflight::check(root, plan, opts, permit, runner)?;
157	    let active_ecosystems = active_ecosystems(plan);
158	    // Resolved before the first write, so a workspace that cannot be found stops the run with nothing changed.
159	    let cargo_workspaces = if active_ecosystems.contains(&Ecosystem::Cargo) {
160	        touched_cargo_workspaces(root, plan)?
161	    } else {
162	        BTreeSet::new()
163	    };
164	    let lockfile_dirs = lockfile_dirs(root, plan, &active_ecosystems)?;
165	    let classification = classify_manifest_writes(plan);
166	
167	    for step in write_steps(plan, &classification) {
168	        modified_paths.push(apply_write_step(&step, plan, root, &ctx, permit)?);
169	    }
170	
171	    if !opts.transient {
172	        for cl in &plan.changelog_writes {
173	            let rendered = crate::changelog::render_section(&cl.input)?;
174	            crate::changelog::prepend(
175	                root,
176	                &cl.changelog_path,
177	                &cl.input.package.display_name(),
178	                &rendered,
179	                permit,
180	            )?;
181	            modified_paths.push(cl.changelog_path.clone());
182	        }
183	
184	        for cs_path in &plan.consumed_changesets {
185	            deferred_deletions.push(cs_path.clone());
186	        }
187	
188	        if let Some(ref pre_state) = plan.pre_state_update {
189	            // Written from `plan.pre_json_path`, not derived from `consumed_changesets` (always empty in pre mode).
190	            let rel_pre_path = plan.pre_json_path.clone();
191	            let pre_path = root.join(&rel_pre_path);
192	            let text = match &plan.pre_json_original_text {
193	                Some(existing) => callisto_model::format::write_pre_json_preserving(pre_state, existing),
194	                None => callisto_model::format::write_pre_json(pre_state),
195	            };
196	            callisto_manifests::atomic::atomic_write(&pre_path, &text, permit).map_err(|e| GraphError::ApplyIo {
197	                path: rel_pre_path.clone(),
198	                message: e.to_string(),
199	            })?;
200	            modified_paths.push(rel_pre_path);
201	        } else if let Some(rel_pre_path) = &plan.delete_pre_json {
202	            deferred_deletions.push(rel_pre_path.clone());
203	        }
204	    }
205	
206	    // Must run before the staging loop below, so refreshed lockfiles are on disk to be staged.
207	    if opts.refresh_lockfiles {
208	        let refresh_results = refresh_lockfiles(runner, root, &cargo_workspaces, &lockfile_dirs)?;
209	        if !refresh_results.is_empty() {
210	            outcome.lockfile_refresh_results = Some(refresh_results);
211	        }
212	    }
213	
214	    // Stage each lockfile of an active ecosystem that exists beside the workspace the plan wrote into.
215	    let beside = |dirs: &BTreeSet<PathBuf>, names: &[&str]| -> Vec<PathBuf> {
216	        dirs.iter()
217	            .flat_map(|dir| names.iter().map(move |name| dir.join(name)))
218	            .collect()
219	    };
220	    let candidates = beside(&lockfile_dirs.npm, &NPM_LOCKFILES)
221	        .into_iter()
222	        .chain(beside(&lockfile_dirs.pypi, &PYPI_LOCKFILES));
223	    let mut lockfile_paths: Vec<PathBuf> = Vec::new();
224	    for p in candidates {
225	        if path_exists(root, &p)? && !modified_paths.contains(&p) {
226	            lockfile_paths.push(p.clone());
227	            modified_paths.push(p);
228	        }
229	    }
230	    for lockfile in cargo_workspaces.iter().map(|workspace| cargo_lockfile(workspace)) {
231	        if path_exists(root, &lockfile)? && !modified_paths.contains(&lockfile) {
232	            lockfile_paths.push(lockfile.clone());
233	            modified_paths.push(lockfile);
234	        }
235	    }
236	
237	    // A lockfile that a .gitignore ignores (a library's `Cargo.lock`, say) is not meant to be committed: refreshed on disk,
238	    // never staged. Anything else the plan stages was checked before the first write.
239	    if !opts.transient {
240	        let ignored = preflight::ignored_paths(runner, root, &lockfile_paths)?;
241	        modified_paths.retain(|path| !ignored.contains(path));
242	    }
243	
244	    if !opts.transient && (!modified_paths.is_empty() || !deferred_deletions.is_empty()) {
245	        // Stage all written release state before consuming its inputs. If a refresh or add fails,
246	        // the changesets/pre-state remain available; if removal staging fails, the manifest diff
247	        // still identifies the interrupted run.
248	        let mut existing = Vec::new();
249	        let mut deleted = Vec::new();
250	        for path in &modified_paths {
251	            if path_exists(root, path)? {
252	                existing.push(path);
253	            } else {
254	                deleted.push(path);
255	            }
256	        }
257	
258	        if !existing.is_empty() {
259	            run_git_on_paths(runner, root, &["add", "--"], &existing)?;
260	        }
261	
262	        if !deleted.is_empty() {
263	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deleted)?;
264	        }
265	
266	        if !deferred_deletions.is_empty() {
267	            let deferred: Vec<&PathBuf> = deferred_deletions.iter().collect();
268	            run_git_on_paths(runner, root, &["rm", "--cached", "--ignore-unmatch", "--"], &deferred)?;
269	
270	            // Keep the inputs on disk until their removal is staged so a failed index update can be retried.
271	            for path in &deferred_deletions {
272	                match fs::remove_file(root.join(path)) {
273	                    Ok(()) => {}
274	                    Err(e) if e.kind() == std::io::ErrorKind::NotFound => {}
275	                    Err(e) => {
276	                        return Err(GraphError::ApplyIo {
277	                            path: path.clone(),
278	                            message: e.to_string(),
279	                        })
280	                    }
281	                }
282	            }
283	            modified_paths.extend(deferred_deletions.iter().cloned());
284	        }
285	
286	        outcome.staged = modified_paths;
287	    }
288	
289	    Ok(outcome)
290	}
291	
292	/// One physical write of a version plan, in the order it must happen.
293	enum WriteStep<'p> {
294	    /// One load/mutate/persist cycle over a manifest only the `Manifest` trait writes: the
295	    /// version bump (idempotency-guarded) first, then every dependency rewrite, one persist.
296	    Manifest {
297	        path: &'p PathBuf,
298	        group: &'p ManifestWriteGroup,
299	    },
300	    /// The same cycle for a Cargo workspace root only the `WorkspaceCargoResolver` writes. Its
301	    /// writes carry no idempotency precondition.
302	    WorkspaceRoot {
303	        root_manifest: &'p PathBuf,
304	        group: &'p ManifestWriteGroup,
305	    },
306	    /// Mixed-routing manifests (written through both routes) are never batched: each write is
307	    /// its own load/persist, strictly in plan order.
308	    MixedManifestVersion {
309	        path: &'p PathBuf,
310	        bump: &'p PlannedBump,
311	    },
312	    MixedWorkspaceVersion {
313	        root_manifest: &'p PathBuf,
314	        to: &'p Version,
315	    },
316	    MixedManifestRewrite {
317	        path: &'p PathBuf,
318	        rewrite: &'p SpecRewrite,
319	    },
320	    MixedWorkspaceRewrite {
321	        root_manifest: &'p PathBuf,
322	        rewrite: &'p SpecRewrite,
323	    },
324	    PlatformVersion(&'p PlatformWrite),
325	    OptionalDependencies(&'p OptionalDepUpdate),
326	}
327	
328	/// Orders every manifest write once, so execution is a single `match` and the per-file order
329	/// (bump, then rewrites, then one persist) is data rather than control flow.
330	fn write_steps<'p>(plan: &'p VersionPlan, classification: &'p ManifestWriteClassification) -> Vec<WriteStep<'p>> {
331	    let mut steps = Vec::new();
332	    for (path, group) in &classification.batched {
333	        steps.push(WriteStep::Manifest { path, group });
334	    }
335	    for (root_manifest, group) in &classification.resolver_batched {
336	        steps.push(WriteStep::WorkspaceRoot { root_manifest, group });
337	    }
338	    for bump in &plan.bumps {
339	        for write in &bump.writes {
340	            match write {
341	                VersionWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
342	                    steps.push(WriteStep::MixedManifestVersion { path, bump });
343	                }
344	                VersionWriteTarget::CargoWorkspacePackage { root_manifest }
345	                    if !classification.resolver_batched.contains_key(root_manifest) =>
346	                {
347	                    steps.push(WriteStep::MixedWorkspaceVersion {
348	                        root_manifest,
349	                        to: &bump.to,
350	                    });
351	                }
352	                _ => {}
353	            }
354	        }
355	    }
356	    for rewrite in &plan.rewrites {
357	        match &rewrite.key.target {
358	            DepWriteTarget::Manifest(path) if classification.excluded.contains(path) => {
359	                steps.push(WriteStep::MixedManifestRewrite { path, rewrite });
360	            }
361	            DepWriteTarget::CargoWorkspaceDependency { root_manifest }
362	                if !classification.resolver_batched.contains_key(root_manifest) =>
363	            {
364	                steps.push(WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite });
365	            }
366	            _ => {}
367	        }
368	    }
369	    steps.extend(plan.platform_writes.iter().map(WriteStep::PlatformVersion));
370	    steps.extend(plan.optional_dep_updates.iter().map(WriteStep::OptionalDependencies));
371	    steps
372	}
373	
374	/// Performs one step and returns the path to stage.
375	fn apply_write_step(
376	    step: &WriteStep<'_>,
377	    plan: &VersionPlan,
378	    root: &Path,
379	    ctx: &OpenContext<'_>,
380	    permit: &ApplyPermit,
381	) -> Result<PathBuf, GraphError> {
382	    match step {
383	        WriteStep::Manifest { path, group } => {
384	            let mut handle = open_canonical(path, ctx)?;
385	            let mut mutated = false;
386	            if let Some((bump_idx, target_version)) = &group.bump {
387	                let bump = &plan.bumps[*bump_idx];
388	                mutated = write_version_guarded(handle.as_mut(), path, &bump.from, target_version, permit)?;
389	            }
390	            for rewrite_idx in &group.rewrite_indices {
391	                rewrite_dependency(handle.as_mut(), &plan.rewrites[*rewrite_idx], permit)?;
392	                mutated = true;
393	            }
394	            if mutated {
395	                handle.persist(permit)?;
396	            }
397	            Ok((*path).clone())
398	        }
399	        WriteStep::WorkspaceRoot { root_manifest, group } => {
400	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
401	            let mut mutated = false;
402	            if let Some((_, target_version)) = &group.bump {
403	                ws_res.write_version(target_version, permit)?;
404	                mutated = true;
405	            }
406	            for rewrite_idx in &group.rewrite_indices {
407	                let rewrite = &plan.rewrites[*rewrite_idx];
408	                ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
409	                mutated = true;
410	            }
411	            if mutated {
412	                ws_res.persist(permit)?;
413	            }
414	            Ok((*root_manifest).clone())
415	        }
416	        WriteStep::MixedManifestVersion { path, bump } => {
417	            let mut handle = open_canonical(path, ctx)?;
418	            if write_version_guarded(handle.as_mut(), path, &bump.from, &bump.to, permit)? {
419	                handle.persist(permit)?;
420	            }
421	            Ok((*path).clone())
422	        }
423	        WriteStep::MixedWorkspaceVersion { root_manifest, to } => {
424	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
425	            ws_res.write_version(to, permit)?;
426	            ws_res.persist(permit)?;
427	            Ok((*root_manifest).clone())
428	        }
429	        WriteStep::MixedManifestRewrite { path, rewrite } => {
430	            let mut handle = open_canonical(path, ctx)?;
431	            rewrite_dependency(handle.as_mut(), rewrite, permit)?;
432	            handle.persist(permit)?;
433	            Ok((*path).clone())
434	        }
435	        WriteStep::MixedWorkspaceRewrite { root_manifest, rewrite } => {
436	            let mut ws_res = WorkspaceCargoResolver::load_at(root, root_manifest)?;
437	            ws_res.write_dependency(&rewrite.key.name, rewrite.to.clone(), permit)?;
438	            ws_res.persist(permit)?;
439	            Ok((*root_manifest).clone())
440	        }

