199	pub fn aggregate<D, I>(
200	    graph: &D,
201	    identity: &IdentityIndex,
202	    config: &ResolvedConfig,
203	    git: &GitAccess<'_>,
204	    tags: &TagIndex,
205	    base_versions: &BTreeMap<PackageId, Version>,
206	    pre: Option<&callisto_model::format::PreState>,
207	    inference: &I,
208	) -> Result<Aggregation, GraphError>
209	where
210	    D: DependencyResolver,
211	    I: SeverityInference,
212	{
213	    let loaded = load_changesets(&config.root, config)?;
214	    let mut agg = Aggregation::default();
215	    // Inference reads `since..HEAD`; in a shallow clone that range is silently shorter than the real one.
216	    if graph.packages().any(|pkg| pkg.release_trigger == ReleaseTrigger::Auto) {
217	        git.require_full_history()?;
218	    }
219	
220	    for pkg in graph.packages() {
221	        let cur_sev = agg.severities.get(&pkg.id).copied().unwrap_or(Severity::None);
222	        let pathspecs: Vec<PathBuf> = crate::changed::package_paths(pkg);
223	        let last_tag = tags.last_tag(&pkg.id);
224	        let cur_ver = last_tag
225	            .map(|t| t.version.clone())
226	            .or_else(|| base_versions.get(&pkg.id).cloned())
227	            .ok_or_else(|| {
228	                GraphError::Manifest(callisto_model::ManifestError::MissingField {
229	                    path: pkg.manifests.first().map(|m| m.path.clone()).unwrap_or_default(),
230	                    field: "version",
231	                })
232	            })?;
233	
234	        let native_names: Vec<_> = identity.native_names(&pkg.id).collect();
235	        let policy = resolve_package_config(&native_names, config)
236	            .and_then(|pcfg| pcfg.pre_major_inference)
237	            .unwrap_or(PreMajorInferencePolicy::Off);
238	
239	        // release_trigger: Changeset packages take severity from pending changesets only --
240	        // commit inference must not run for them, so neither does resolving its window.
241	        let inferred = if pkg.release_trigger == ReleaseTrigger::Auto {
242	            let since = last_tag
243	                .map(|t| resolve_since(git, tags, t.name.as_str()))
244	                .transpose()?;
245	            let window = crate::infer::InferenceWindowSpec {
246	                pathspecs: &pathspecs,
247	                since,
248	                current_version: &cur_ver,
249	                has_prior_release: last_tag.is_some(),
250	                policy,
251	            };
252	            inference.infer(pkg, git, window)
253	        } else {
254	            Ok(None)
255	        };
256	
257	        match inferred {
258	            Ok(Some(outcome)) => {
259	                if outcome.severity > cur_sev {
260	                    agg.severities.insert(pkg.id.clone(), outcome.severity);
261	                    agg.reasons.insert(
262	                        pkg.id.clone(),
263	                        BumpReason::Inference {
264	                            commits: outcome.commit_count,
265	                            remapped: outcome.remapped,
266	                        },
267	                    );
268	                    agg.named_by.insert(pkg.id.clone(), NamedBy::Inference);
269	                    agg.inference_commits.insert(pkg.id.clone(), outcome.commits.clone());
270	                }
271	            }
272	            Ok(None) => {}
273	            Err(e) => {
274	                agg.diagnostics.push(Diagnostic {
275	                    code: callisto_model::DiagnosticCode::PreMajorInferenceInert,
276	                    severity: callisto_model::DiagnosticSeverity::Warning,
277	                    message: format!("Commit inference failed for package `{}`: {e}", pkg.id.display_name()),
278	                    package: Some(pkg.id.clone()),
279	                    path: None,
280	                    governed_by: None,
281	                    escalated_by: None,
282	                });
283	            }
284	        }
285	    }
286	
287	    // During a pre-release cycle (PreMode::Pre) changesets must NOT be consumed:
288	    // they remain on disk so they can be re-applied when the cycle exits.
289	    let is_pre_mode = pre
290	        .map(|s| s.mode == callisto_model::format::PreMode::Pre)
291	        .unwrap_or(false);
292	    // Ids already recorded in pre.json still resolve for severity, but are not re-added to the changelog.
293	    let already_recorded: std::collections::HashSet<&str> = pre
294	        .map(|s| s.changesets.iter().map(String::as_str).collect())
295	        .unwrap_or_default();
296	    let mut recorded_only: std::collections::HashSet<PackageId> = std::collections::HashSet::new();
297	
298	    for cs in loaded {
299	        let is_already_recorded = is_pre_mode && already_recorded.contains(cs.id.as_str());
300	        // Defer adding to `consumed` until after we confirm at least one entry
301	        // resolved to a real workspace package. A changeset where every entry
302	        // names a removed package must NOT be consumed (which would delete it
303	        // on disk); instead, an UnknownPackage diagnostic is emitted and the
304	        // file is left for the user to clean up manually.
305	        //
306	        // A changeset with a MIX of resolved and unresolved entries is ignored
307	        // in full, not applied in part: it stays on disk (so it cannot lose the
308	        // unresolved entry's bump), and applying its resolved entries every
309	        // run would bump those packages again each time while it stays.
310	        let mut has_unresolved = false;
311	        let mut resolved = Vec::new();
312	        for entry in cs.changeset.entries {
313	            let unresolved = match PackageId::parse(&entry.name) {
314	                Err(_) => Some("contains invalid package name"),
315	                Ok(id) => match resolve_target_package(graph.packages(), identity, &id)? {
316	                    Some(target_pkg) => {
317	                        resolved.push((entry, target_pkg));
318	                        continue;
319	                    }
320	                    None => Some("references a package that is not in the workspace:"),
321	                },
322	            };
323	            if let Some(what) = unresolved {
324	                has_unresolved = true;
325	                agg.diagnostics.push(Diagnostic {
326	                    code: callisto_model::DiagnosticCode::UnknownPackage,
327	                    severity: callisto_model::DiagnosticSeverity::Warning,
328	                    message: format!(
329	                        "Changeset `{}` {what} `{}`; none of its entries apply until this entry is fixed or removed",
330	                        cs.path.display(),
331	                        entry.name
332	                    ),
333	                    package: None,
334	                    path: Some(cs.path.clone()),
335	                    governed_by: None,
336	                    escalated_by: None,
337	                });
338	            }
339	        }
340	        if has_unresolved {
341	            continue;
342	        }
343	        let mut matched_any = false;
344	        for (entry, target_pkg) in resolved {
345	            matched_any = true;
346	            let canonical_id = target_pkg.id.clone();
347	            let cur_sev = agg.severities.get(&canonical_id).copied().unwrap_or(Severity::None);
348	            if entry.severity > cur_sev {
349	                agg.severities.insert(canonical_id.clone(), entry.severity);
350	                agg.reasons.insert(
351	                    canonical_id.clone(),
352	                    BumpReason::Changeset {
353	                        changesets: vec![cs.id.clone()],
354	                    },
355	                );
356	                agg.named_by.insert(canonical_id.clone(), NamedBy::Changeset);
357	            }
358	
359	            if entry.severity != Severity::None && is_already_recorded {
360	                recorded_only.insert(canonical_id.clone());
361	            }
362	            if entry.severity != Severity::None && !is_already_recorded {
363	                // In pre-release mode use the pre-cycle entry version as the
364	                // changelog "from" baseline so the log covers the full pre
365	                // range rather than reflecting live (pre-tagged) versions.
366	                let pkg_ver = if is_pre_mode {
367	                    pre.and_then(|s| crate::pre_initial_version(s, &canonical_id))
368	                        .cloned()
369	                        .or_else(|| base_versions.get(&canonical_id).cloned())
370	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
371	                } else {
372	                    tags.last_tag(&canonical_id)
373	                        .map(|t| t.version.clone())
374	                        .or_else(|| base_versions.get(&canonical_id).cloned())
375	                        .unwrap_or_else(|| Version::semver(0, 0, 0))
376	                };
377	                let cl_input = agg
378	                    .changelog_inputs
379	                    .entry(canonical_id.clone())
380	                    .or_insert_with(|| ChangelogInput {
381	                        package: canonical_id.clone(),
382	                        from: pkg_ver,
383	                        to: None,
384	                        entries: Vec::new(),
385	                    });
386	                cl_input.entries.push(ChangelogEntry {
387	                    severity: entry.severity,
388	                    source: ChangeSource::Changeset {
389	                        filename: cs.id.clone(),
390	                        summary: cs.changeset.summary.clone(),
391	                    },
392	                });
393	            }
394	        }
395	        if matched_any {
396	            if is_pre_mode {
397	                // Records newly-seen ids so a rerun treats them as already-applied and skips the changelog entry.
398	                if !is_already_recorded {
399	                    agg.new_pre_changesets.push(cs.id.clone());
400	                }
401	            } else {
402	                agg.consumed.push(cs.path.clone());
403	            }
404	        }
405	    }
406	
407	    // A package whose only changesets are already recorded in `pre.json` has nothing new to release, so a rerun
408	    // plans no further prerelease for it; recorded changesets still count when a new one names the package.
409	    for id in recorded_only {
410	        if !agg.changelog_inputs.contains_key(&id) && agg.named_by.get(&id) == Some(&NamedBy::Changeset) {
411	            agg.severities.remove(&id);
412	            agg.reasons.remove(&id);
413	            agg.named_by.remove(&id);
414	        }
415	    }
416	
417	    loop {
418	        let mut changed = false;
419	        if union_fixed(&mut agg, &config.groups, base_versions) {
420	            changed = true;
421	        }
422	        if union_linked(&mut agg, &config.groups, base_versions) {
423	            changed = true;
424	        }
425	        if !changed {
426	            break;
427	        }
428	    }
429	
430	    Ok(agg)
431	}
432	
433	pub(crate) fn union_fixed(
434	    agg: &mut Aggregation,
435	    groups: &GroupTable,
436	    base_versions: &BTreeMap<PackageId, Version>,
437	) -> bool {
438	    let mut changed = false;
439	    for g in groups.fixed.values() {
440	        let target = g.max_severity(&agg.severities);
441	        if target == Severity::None {
442	            continue;
443	        }
444	
445	        for m in g.package_members().cloned().collect::<Vec<_>>() {
446	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
447	            if target > cur {
448	                // Guard against stale group members: a package listed in the
449	                // config group that was subsequently removed from the workspace
450	                // must not be inserted into severities.  Doing so causes
451	                // `bump_target` in `solve_cascade` to call
452	                // `input.base.get(stale_id)` -> `None` ->
453	                // `Err(GraphError::Manifest(MissingField))`, which surfaces as
454	                // a misleading crash.  Emit a warning instead and skip.
455	                if !base_versions.contains_key(&m) {
456	                    agg.diagnostics.push(Diagnostic {
457	                        code: callisto_model::DiagnosticCode::UnknownPackage,
458	                        severity: callisto_model::DiagnosticSeverity::Warning,
459	                        message: format!(
460	                            "Fixed group `{}` references package `{}` which is not in the \
461	                             workspace; the stale group member is skipped. Remove it from \
462	                             callisto.toml to silence this warning.",
463	                            g.name,
464	                            m.display_name()
465	                        ),
466	                        package: Some(m.clone()),
467	                        path: None,
468	                        governed_by: Some(callisto_model::ConfigKey::FIXED_GROUP),
469	                        escalated_by: None,
470	                    });
471	                    continue;
472	                }
473	                agg.severities.insert(m.clone(), target);
474	                agg.reasons
475	                    .insert(m.clone(), BumpReason::FixedGroupUnion { group: g.name.clone() });
476	                changed = true;
477	            }
478	        }
479	    }
480	    changed
481	}
482	
483	pub(crate) fn union_linked(
484	    agg: &mut Aggregation,
485	    groups: &GroupTable,
486	    base_versions: &BTreeMap<PackageId, Version>,
487	) -> bool {
488	    let mut changed = false;
489	    for g in groups.linked.values() {
490	        let named_any = g.package_members().any(|id| agg.named_by.contains_key(id));
491	        if !named_any {
492	            continue;
493	        }
494	
495	        // Unlike `union_fixed`'s max_severity (over every member), a linked
496	        // group's target severity comes only from members a changeset or
497	        // inference actually named -- an unnamed sibling's stale leftover
498	        // severity from an earlier fixed-point round must not count.
499	        let target_sev = g
500	            .package_members()
501	            .filter(|id| agg.named_by.contains_key(*id))
502	            .filter_map(|id| agg.severities.get(id).copied())
503	            .max()
504	            .unwrap_or(Severity::None);
505	
506	        for m in g.package_members().cloned().collect::<Vec<_>>() {
507	            let cur = agg.severities.get(&m).copied().unwrap_or(Severity::None);
508	            if target_sev > cur {
509	                // Guard against stale linked-group members, same rationale as
510	                // in `union_fixed`: a removed package must not enter
511	                // `agg.severities`, which would cause `bump_target` to crash.
512	                if !base_versions.contains_key(&m) {
513	                    agg.diagnostics.push(Diagnostic {
514	                        code: callisto_model::DiagnosticCode::UnknownPackage,
515	                        severity: callisto_model::DiagnosticSeverity::Warning,
516	                        message: format!(
517	                            "Linked group `{}` references package `{}` which is not in the \
518	                             workspace; the stale group member is skipped. Remove it from \
519	                             callisto.toml to silence this warning.",
520	                            g.name,
521	                            m.display_name()
522	                        ),
523	                        package: Some(m.clone()),
524	                        path: None,
525	                        governed_by: Some(callisto_model::ConfigKey::LINKED_GROUP),
526	                        escalated_by: None,
527	                    });
528	                    continue;
529	                }
530	                agg.severities.insert(m.clone(), target_sev);
531	                agg.reasons
532	                    .insert(m.clone(), BumpReason::LinkedGroupUnion { group: g.name.clone() });
533	                changed = true;
534	            }
535	        }
536	    }
537	    changed
538	}
