525	#[allow(clippy::too_many_arguments)]
526	fn raise<D: DependencyResolver>(
527	    pkg: &PackageId,
528	    sev: Severity,
529	    decision: &CascadeDecision,
530	    via: &PackageId,
531	    edge: &DepEdge,
532	    dependency_to: &Version,
533	    out: &mut CascadeOutcome,
534	    groups: &GroupTable,
535	    worklist: &mut BTreeSet<PackageId>,
536	    input: &CascadeInput<'_, D>,
537	) -> Result<bool, GraphError> {
538	    let cur_sev = out.severities.get(pkg).copied().unwrap_or(Severity::None);
539	    if sev <= cur_sev {
540	        return Ok(false);
541	    }
542	
543	    out.severities.insert(pkg.clone(), sev);
544	
545	    let new_reason = if decision.escalated {
546	        BumpReason::PeerEscalation {
547	            via: via.clone(),
548	            spec: edge.spec.render(),
549	        }
550	    } else {
551	        BumpReason::Cascade {
552	            via: via.clone(),
553	            dep_kind: edge.kind,
554	            spec: edge.spec.render(),
555	            dependency_to: dependency_to.clone(),
556	        }
557	    };
558	    out.reasons.insert(pkg.clone(), new_reason);
559	
560	    if let Some(ref gov) = decision.governed_by {
561	        out.governed_by.insert(pkg.clone(), gov.clone());
562	    }
563	
564	    let new_t = bump_target(pkg, sev, input)?;
565	    out.targets.insert(pkg.clone(), new_t);
566	    worklist.insert(pkg.clone());
567	
568	    for sib in groups.fixed_siblings(pkg) {
569	        let sib_sev = out.severities.get(sib).copied().unwrap_or(Severity::None);
570	        if sev > sib_sev {
571	            out.severities.insert(sib.clone(), sev);
572	            out.reasons.insert(
573	                sib.clone(),
574	                BumpReason::FixedGroupUnion {
575	                    group: groups
576	                        .fixed_group_of(pkg)
577	                        .expect("a fixed-group sibling implies the package has a fixed group")
578	                        .name
579	                        .clone(),
580	                },
581	            );
582	            let sib_t = bump_target(sib, sev, input)?;
583	            out.targets.insert(sib.clone(), sib_t);
584	            worklist.insert(sib.clone());
585	        }
586	    }
587	
588	    Ok(true)
589	}
590	
591	pub(crate) fn convergence_bound(package_count: usize) -> usize {
592	    4 * package_count + 1
593	}
594	
595	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
596	pub enum DepWriteTarget {
597	    Manifest(PathBuf),
598	    CargoWorkspaceDependency { root_manifest: PathBuf },
599	}
600	
601	#[derive(Clone, Debug, PartialEq, Eq, PartialOrd, Ord)]
602	pub struct RewriteKey {
603	    pub target: DepWriteTarget,
604	    pub name: String,
605	    pub kind: Option<DepKind>,
606	    pub locator: DepLocator,
607	}
608	
609	#[derive(Clone, Debug, PartialEq, Eq)]
610	pub struct SpecRewrite {
611	    pub key: RewriteKey,
612	    pub dependency: PackageId,
613	    pub from: DepSpec,
614	    pub to: DepSpec,
615	}
616	
617	pub enum RewriteOutcome {
618	    Rewritten(DepSpec),
619	    LeftAlone(Diagnostic),
620	}
621	
622	/// Rewrites one dependency edge toward `new`. A range a consumer's published manifest would keep excluding `new`
623	/// stops the run; only a dev dependency, which consumers never install, is left alone with a warning.
624	pub(crate) fn rewrite_edge(edge: &DepEdge, new: &Version, cfg: &CascadeConfig) -> Result<RewriteOutcome, GraphError> {
625	    let eco = manifest_ecosystem(&edge.from_manifest);
626	    match rewrite_spec(&edge.spec, new, eco, cfg) {
627	        RewriteOutcome::LeftAlone(_) if edge.kind != DepKind::Dev => Err(GraphError::UnrewritableRange {
628	            dependent: edge.from.display_name(),
629	            dependency: edge.to.display_name(),
630	            spec: edge.spec.render(),
631	            version: new.render().to_string(),
632	            manifest: edge.from_manifest.display().to_string(),
633	        }),
634	        outcome => Ok(outcome),
635	    }
636	}
637	
638	pub fn rewrite_spec(original: &DepSpec, new: &Version, eco: Ecosystem, cfg: &CascadeConfig) -> RewriteOutcome {
639	    if !cfg.preserve_npm_ranges && eco == Ecosystem::Npm && !matches!(original, DepSpec::WorkspaceProtocol(_)) {
640	        return RewriteOutcome::Rewritten(DepSpec::Exact(new.clone()));
641	    }
642	
643	    // A rewrite that still excludes `new` is no rewrite: the dependent would publish a range its dependency cannot meet.
644	    match callisto_manifests::round_trip(eco, original, new)
645	        .filter(|rewritten| matches!(coverage(rewritten, new), Ok(Coverage::Covers | Coverage::Unknown)))
646	    {
647	        Some(rewritten) => RewriteOutcome::Rewritten(rewritten),
648	        _ => RewriteOutcome::LeftAlone(Diagnostic {
649	            code: DiagnosticCode::RangeNotRoundTrippable,
650	            severity: DiagnosticSeverity::Warning,
651	            message: format!(
652	                "spec `{}` could not be round-tripped toward version `{}`",
653	                original.render(),
654	                new.render()
655	            ),
656	            package: None,
657	            path: None,
658	            governed_by: Some(ConfigKey::CASCADE_PRESERVE_NPM_RANGES),
659	            escalated_by: None,
660	        }),
