11	#[derive(Clone, Debug, Default)]
12	pub struct GroupCheckOutcome {
13	    pub new_members: BTreeMap<GroupName, Vec<PackageId>>,
14	    pub diagnostics: Vec<Diagnostic>,
15	}
16	
17	pub fn pre_mutation_checks<D: DependencyResolver>(
18	    _graph: &D,
19	    groups: &GroupTable,
20	    base: &BTreeMap<PackageId, Version>,
21	    tags: &TagIndex,
22	    napi: &NapiTargetsIndex,
23	    root: &Path,
24	) -> Result<GroupCheckOutcome, GraphError> {
25	    let mut outcome = GroupCheckOutcome::default();
26	
27	    for g in groups.fixed.values() {
28	        let released: Vec<PackageId> = g
29	            .package_members()
30	            .filter(|id| tags.last_tag(id).is_some())
31	            .cloned()
32	            .collect();
33	
34	        let fresh: Vec<PackageId> = g
35	            .package_members()
36	            .filter(|id| tags.last_tag(id).is_none())
37	            .cloned()
38	            .collect();
39	
40	        let pairs: Vec<(PackageId, Version)> = released
41	            .iter()
42	            .filter_map(|id| base.get(id).map(|v| (id.clone(), v.clone())))
43	            .collect();
44	
45	        if pairs.len() > 1 {
46	            let first_v = &pairs[0].1;
47	            let mut divergent = false;
48	            for (_id, v) in &pairs[1..] {
49	                if v.grammar() != first_v.grammar() {
50	                    return Err(GraphError::GroupGrammarMismatch {
51	                        group: g.name.clone(),
52	                        members: pairs,
53	                    });
54	                }
55	                if Version::compare(v, first_v).ok() != Some(std::cmp::Ordering::Equal) {
56	                    divergent = true;
57	                }
58	            }
59	            if divergent {
60	                return Err(GraphError::FixedGroupDivergent {
61	                    group: g.name.clone(),
62	                    members: pairs,
63	                });
64	            }
65	        }
66	
67	        if !fresh.is_empty() {
68	            outcome.new_members.insert(g.name.clone(), fresh);
69	        }
70	
71	        // napi.targets drift cross-check.
72	        if let Some(declared) = napi.declared_for(&g.name) {
73	            outcome.diagnostics.extend(napi_drift(g, declared, root));
74	        }
75	    }
76	
77	    Ok(outcome)
78	}
79	
80	/// Computes `base`'s next version under `severity`, grammar-aware (SemVer vs PEP 440) and, in pre-release mode,
81	/// anchored on `pre.json`'s pinned `initialVersions` entry rather than the live on-disk version. Shared by
82	/// `cascade::bump_target` and `fixed_group_target`, and rejects any result that sorts behind `base`.
83	pub fn versioned_bump(
84	    package: &PackageId,
85	    base: &Version,
86	    severity: Severity,
87	    pre: Option<&callisto_model::format::PreState>,
88	) -> Result<Version, GraphError> {
89	    let versioning = callisto_model::format::versioning_for(base.grammar())
90	        .ok_or(callisto_model::format::BumpError::UnsupportedGrammar {
91	            grammar: base.grammar(),
92	        })
93	        .map_err(GraphError::Bump)?;
94	
95	    // Compares against the pinned anchor in pre mode, not live on-disk, which may lead a different pre-release cycle.
96	    let (bumped_from, next) = match pre {
97	        Some(pre) if pre.mode == callisto_model::format::PreMode::Pre => {
98	            let pinned_base = crate::pre_initial_version(pre, package).unwrap_or(base);
99	            let next = versioning
100	                .bump_prerelease(pinned_base, severity, &pre.tag, base)
101	                .map_err(GraphError::Bump)?;
102	            (pinned_base.clone(), next)
103	        }
104	        _ => {
105	            let next = versioning.bump(base, severity).map_err(GraphError::Bump)?;
106	            (base.clone(), next)
107	        }
108	    };
109	
110	    if matches!(Version::compare(&next, &bumped_from), Ok(std::cmp::Ordering::Less)) {
111	        return Err(GraphError::VersionRegression {
112	            package: package.clone(),
113	            from: bumped_from,
114	            to: next,
115	        });
116	    }
117	
118	    Ok(next)
119	}
120	
121	/// Computes a fixed group's shared alignment target. `live_members` must already be filtered to ids present in
122	/// `base` (`solve_cascade` drops stale members). The alignment base is a released member's on-disk version (an
123	/// error, not a silent default, if that member is missing from `base`), or else the highest on-disk untagged version.
124	pub fn fixed_group_target(
125	    group: &GroupName,
126	    live_members: &[PackageId],
127	    base: &BTreeMap<PackageId, Version>,
128	    max_sev: Severity,
129	    tags: &TagIndex,
130	    pre: Option<&callisto_model::format::PreState>,
131	) -> Result<Version, GraphError> {
132	    let released: Vec<&PackageId> = live_members.iter().filter(|id| tags.last_tag(id).is_some()).collect();
133	
134	    let (anchor, aligned_base) = if !released.is_empty() {
135	        let anchor = released[0];
136	        let v = base
137	            .get(anchor)
138	            .cloned()
139	            .ok_or_else(|| GraphError::FixedGroupTaggedMemberMissingBase {
140	                group: group.clone(),
141	                member: anchor.clone(),
142	            })?;
143	        (anchor.clone(), v)
144	    } else {
145	        let mut untagged = live_members
146	            .iter()
147	            .filter_map(|id| base.get(id).map(|v| (id.clone(), v.clone())));
148	        let mut best = untagged
149	            .next()
150	            .ok_or_else(|| GraphError::FixedGroupEmpty { group: group.clone() })?;
151	        for (id, v) in untagged {
152	            match Version::compare(&v, &best.1) {
153	                Ok(std::cmp::Ordering::Greater) => best = (id, v),
154	                Ok(_) => {}
155	                Err(_) => {
156	                    return Err(GraphError::GroupGrammarMismatch {
157	                        group: group.clone(),
158	                        members: live_members
159	                            .iter()
160	                            .filter_map(|m| base.get(m).map(|v| (m.clone(), v.clone())))
161	                            .collect(),
162	                    });
163	                }
164	            }
165	        }
166	        best
167	    };
168	
169	    versioned_bump(&anchor, &aligned_base, max_sev, pre)
170	}
