5	pub(crate) fn indent_changeset_summary(summary: &str) -> Option<String> {
6	    let summary = summary.trim_end_matches('\n');
7	    if summary.trim().is_empty() {
8	        return None;
9	    }
10	    let mut indented = String::new();
11	    for (index, line) in summary.lines().enumerate() {
12	        if index > 0 {
13	            indented.push('\n');
14	        }
15	        if line.trim().is_empty() {
16	            continue;
17	        }
18	        if index > 0 {
19	            indented.push_str("  ");
20	        }
21	        indented.push_str(line);
22	    }
23	    Some(indented)
24	}
25	
26	pub fn render_section(input: &ChangelogInput) -> Result<String, ChangelogError> {
27	    if input.entries.is_empty() {
28	        return Err(ChangelogError::EmptyInput);
29	    }
30	    for entry in &input.entries {
31	        if entry.severity == callisto_model::Severity::None {
32	            return Err(ChangelogError::SeverityNoneEntry);
33	        }
34	    }
35	
36	    let mut out = String::new();
37	
38	    let heading = match &input.to {
39	        Some(v) => format!("## {}", v.render()),
40	        None => "## Unreleased".to_string(),
41	    };
42	    out.push_str(&heading);
43	    out.push('\n');
44	    out.push('\n');
45	
46	    let mut dep_updates = Vec::new();
47	
48	    for entry in &input.entries {
49	        match &entry.source {
50	            ChangeSource::Changeset { summary, .. } => {
51	                if let Some(indented) = indent_changeset_summary(summary) {
52	                    out.push_str(&format!("- {indented}\n"));
53	                }
54	            }
55	            ChangeSource::Commit { subject, sha } => {
56	                out.push_str(&format!("- {subject} ({})\n", sha.short()));
57	            }
58	            ChangeSource::DependencyUpdate { dependency, to, .. } => {
59	                dep_updates.push((dependency, to));
60	            }
61	            ChangeSource::PeerEscalation { dependency, to } => {
62	                out.push_str(&format!(
63	                    "- Peer dependency `{}` requires `{}`\n",
64	                    dependency.display_name(),
65	                    to.render()
66	                ));
67	            }
68	            ChangeSource::GroupUnion { group, kind } => {
69	                let k_str = match kind {
70	                    GroupKind::Fixed => "fixed",
71	                    GroupKind::Linked => "linked",
72	                };
73	                out.push_str(&format!("- Released together with the `{group}` {k_str} group.\n"));
74	            }
75	            ChangeSource::NewGroupMember { group } => {
76	                out.push_str(&format!("- Joined the `{group}` group at this version.\n"));
77	            }
78	        }
79	    }
80	
81	    if !dep_updates.is_empty() {
82	        out.push_str("- Dependency updates\n");
83	        for (dep, to_ver) in dep_updates {
84	            out.push_str(&format!("  - `{}` → `{}`\n", dep.display_name(), to_ver.render()));
85	        }
86	    }
87	
88	    Ok(out)
89	}
