50	pub fn derive_release_decision<R: callisto_model::CommandRunner, D: DependencyResolver>(
51	    workspace: &Workspace<'_, R, D>,
52	    plan: &VersionPlan,
53	) -> Result<ReleaseDecisionV1, GraphError> {
54	    let mut package_ids = std::collections::BTreeMap::new();
55	    for package in workspace.graph.packages() {
56	        let ids = release_package_ids(&workspace.identity, package)?;
57	        package_ids.insert(package.id.clone(), ids);
58	    }
59	
60	    let mut entries = Vec::new();
61	    for bump in &plan.bumps {
62	        // `plan` is contractually derived from this same workspace
63	        // observation (see doc comment above), so every bump's package must
64	        // already be a key here -- a miss means the plan/workspace pairing
