915	    package_ids: &std::collections::BTreeMap<callisto_model::PackageId, Vec<ReleasePackageId>>,
916	) -> Result<ReleaseInclusionReason, GraphError> {
917	    match reason {
918	        Some(BumpReason::Changeset { .. }) | None => Ok(ReleaseInclusionReason::Changeset),
919	        Some(BumpReason::Inference { .. }) => Ok(ReleaseInclusionReason::Inference),
920	        Some(BumpReason::LinkedGroupUnion { group }) => Ok(ReleaseInclusionReason::LinkedGroup {
921	            group_id: group.to_string(),
922	        }),
923	        Some(BumpReason::FixedGroupUnion { group } | BumpReason::NewGroupMember { group }) => {
924	            Ok(ReleaseInclusionReason::FixedGroup {
925	                group_id: group.to_string(),
926	            })
927	        }
928	        Some(BumpReason::PreRelease { tag }) => Ok(ReleaseInclusionReason::PreReleasePolicy { policy_id: tag.clone() }),
