930	            // `package_ids` is derived from the same workspace graph `via`
931	            // was resolved against, so a miss (or a non-unique release
932	            // identity) here means that pairing broke, not that this is a
933	            // recoverable operator condition.
934	            let source = package_ids
935	                .get(via)
936	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
937	                .ok_or_else(|| GraphError::ReleaseInvariant {
938	                    detail: format!(
939	                        "cascade source package `{}` has no unique release package id",
940	                        via.display_name()
941	                    ),
942	                })?;
943	            Ok(ReleaseInclusionReason::Cascade {
944	                from: source,
945	                edge_kind: format!("{dep_kind:?}"),
946	            })
947	        }
948	        Some(BumpReason::PeerEscalation { via, .. }) => {
949	            let source = package_ids
950	                .get(via)
951	                .and_then(|ids| (ids.len() == 1).then(|| ids[0].clone()))
952	                .ok_or_else(|| GraphError::ReleaseInvariant {
